mapper.select:
select * from pcd_directory_tree_table
where node_parent_id=#{node_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  and node_user_id=#{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  and node_status not in ('trashed', 'deleted');

mapper.update:
update pcd_directory_tree_table
set node_name = #{new_name}
where node_id = #{node_id,typeHandler=org.project.util.UUIDBinaryTypeHandler} and node_user_id = #{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler};

update pcd_directory_tree_table
set node_status = #{new_status}
where node_id = #{node_id,typeHandler=org.project.util.UUIDBinaryTypeHandler} and node_user_id = #{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler};

update pcd_directory_tree_table
set node_parent_id = #{new_parent_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
where node_id = #{node_id,typeHandler=org.project.util.UUIDBinaryTypeHandler} and node_user_id = #{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler};
